*/
     }

     .content {
       display: flex;
       flex-direction: column;
       gap: 10px;
       animation: fadeInUp 0.9s ease-out;
       position: relative;
       z-index: 2;
     }

     .name {
       font-size: 32px;
       font-weight: 700;
       margin: 0;
       color: #F3EFE7;
       letter-spacing: 0.3px;
       text-shadow: 0 2px 10px rgba(0,0,0,0.55);
     }

     .name span.accent {
       color: #6FCF97;
     }

     .tagline {
       font-size: 15px;
       font-weight: 600;
       margin: 0;
       color: #F2A93B;
       letter-spacing: 0.5px;
       text-transform: uppercase;
       text-shadow: 0 1px 6px rgba(0,0,0,0.5);
     }

     .bio {
       font-size: 14.5px;
       line-height: 1.55;
       margin: 4px 0 6px 0;
       color: rgba(243,239,231,0.88);
       max-width: 620px;
       text-shadow: 0 1px 8px rgba(0,0,0,0.5);
     }

     .badges {
       display: flex;
       flex-wrap: wrap;
       gap: 8px;
       margin-top: 4px;
     }

     .badge {
       font-size: 12px;
       font-weight: 600;
       padding: 6px 14px;
       border-radius: 999px;
       border: 1px solid rgba(111,207,151,0.5);
       background: rgba(18,16,28,0.55);
       color: #6FCF97;
       white-space: nowrap;
     }

     .badge.gold {
       border-color: rgba(242,169,59,0.55);
       background: rgba(18,16,28,0.55);
       color: #F2A93B;
     }

     /* Light mode overrides */
     @media (prefers-color-scheme: light) {
       .card {
         color: #12101c;
         border: 1px solid rgba(18,16,28,0.08);
         background-image: url('data:image/jpeg;base64,');
       }
       .name { color: #12101c; text-shadow: none; }
       .bio { color: rgba(18,16,28,0.80); text-shadow: none; }
       .tagline { color: #d98d1f; text-shadow: none; }
       .badge {
         border-color: rgba(46,148,101,0.55);
         background: rgba(243,239,231,0.75);
         color: #2e9465;
       }
       .badge.gold {
         border-color: rgba(217,141,31,0.55);
         background: rgba(243,239,231,0.75);
         color: #d98d1f;
       }
       .avatar {
         border-color: #F3EFE7;
       }
     }
